'use strict';
const fs=require('node:fs'),p=require('node:path'),c=require('node:crypto');const root=fs.realpathSync(__dirname),repo='<CEW_SOURCE>',dir=p.join(repo,'docs/eval/data/quality-type-interactions-2026-10-19');
const hash=b=>c.createHash('sha256').update(b).digest('hex'),read=f=>JSON.parse(fs.readFileSync(p.join(root,f)));
if(fs.existsSync(p.join(root,'posthoc-infinite-stop-amendment.json'))||!fs.existsSync(p.join(root,'posthoc-floatstop-amendment.json')))throw Error('Apply once after shortcircuit amendment');
const e=read('experiment.json'),h=read('infinite-stop-hypothesis.json'),probe=read('posthoc-infinite-stop-probes.json');
if(e.status!=='COMPLETED_ALL_42'||Date.parse(probe.started_at)<=Date.parse(e.finished_at)||hash(fs.readFileSync(p.join(root,'infinite-stop-probes.cjs')))!==h.controller_sha256)throw Error('Must use unchanged proposed controller afterall42close');
if(probe.results.length!==8||probe.results.some(r=>r.cases.length!==2||new Set(r.cases.map(c=>c.case+'/'+c.operation)).size!==2||r.cases.some(c=>c.constructor_exception||!c.constructor_valid||(c.timed_out?c.error!=='ETIMEDOUT':c.exit!==0))))throw Error('Require16 actual valid launches');
const ref=probe.results.find(r=>r.version==='upstream_reference'),parent=probe.results.find(r=>r.version==='parent');if(!parent?.cases.every(c=>c.passed)||!ref?.cases.every(c=>c.passed)||probe.baseline_validation.length!==2||probe.baseline_validation.some(c=>c.exit!==0||c.exception!==probe.expected_exceptions[c.case]))throw Error('Actual parent exception control and reference mustpass');
const oldProbe=read('compatibility-probes.json');for(const r of probe.results)if(oldProbe.results.find(x=>x.version===r.version)?.source_sha256!==r.source_sha256)throw Error('Frozen source drift');
const backup=p.join(root,'before-posthoc-infinite-stop');fs.mkdirSync(backup);for(const f of ['analysis.json','experiment.json','trials.jsonl','trials.csv'])fs.copyFileSync(p.join(dir,f),p.join(backup,f));const report=p.join(repo,'docs/eval/fast-path-type-interactions-2026-10-19.md');fs.copyFileSync(report,p.join(backup,'report.md'));
const a=JSON.parse(fs.readFileSync(p.join(dir,'analysis.json'))),metricHash=hash(JSON.stringify(a.summary)),before=JSON.parse(JSON.stringify(a.supplemental_quality_summary)),arms=['gpt-cew','gpt-trim','gpt-fixed'];
const rows=fs.readFileSync(p.join(dir,'trials.jsonl'),'utf8').trim().split('\n').map(s=>JSON.parse(s));for(const r of rows){if(!('predeclared_checks_passed'in r)||'posthoc_infinite_stop_quality'in r)throw Error('Unexpected score state');r.pre_infinite_stop_checks_passed=r.all_executed_checks_passed;const x=r.task==='more-itertools-1247'?probe.results.find(x=>x.cell===r.cell&&x.run===r.run):null;if(r.task==='more-itertools-1247'&&!x)throw Error('Missing uniform floatstop result');r.posthoc_infinite_stop_quality=x;r.all_executed_checks_passed=r.pre_infinite_stop_checks_passed&&(!x||x.cases.every(c=>c.passed));}
a.supplemental_quality_summary=a.supplemental_quality_summary.map(r=>({...r,all_executed_checks_passed:rows.filter(x=>x.cell===r.cell&&x.all_executed_checks_passed).length,posthoc_infinite_stop_failures:rows.filter(x=>x.cell===r.cell&&x.posthoc_infinite_stop_quality?.cases.some(c=>!c.passed)).length}));
const counts=probe.results.map(r=>({version:r.version,passed:r.cases.filter(c=>c.passed).length,total:2}));
const am={kind:'POSTHOC two infinite-stop termination checks; original46 and previous6posthoc preserved',amended_at:new Date().toISOString(),hypothesis_proposed_at:h.proposed_at,models_finished_at:e.finished_at,actual_probes_started_at:probe.started_at,actual_probes_finished_at:probe.finished_at,actual_queries:16,per_numeric_artifact:2,total_executed_numeric_checks_per_artifact:54,reference_control:'2/2',parent_control:'2/2 actual ValueError',oracle_validation_calls:2,total_process_launches:18,parent_role:'Preserve actual parent exception with valid constructors; no iteration completion claim',controller_sha256:h.controller_sha256,previous_all_executed_summary:before,all_executed_summary:a.supplemental_quality_summary,version_results:counts,models_or_original_artifacts_changed:false,metrics_changed:false,previous_hashes:Object.fromEntries(['analysis.json','experiment.json','trials.jsonl','trials.csv','report.md'].map(f=>[f,hash(fs.readFileSync(p.join(backup,f)))])),procedure_source:fs.readFileSync(__filename,'utf8')};
a.posthoc_infinite_stop_amendment={kind:am.kind,actual_queries:16,total_numeric_checks:54,controller_sha256:h.controller_sha256,previous6posthoc_preserved:true};if(hash(JSON.stringify(a.summary))!==metricHash)throw Error('Metrics changed');
const normalize=v=>JSON.parse(JSON.stringify(v).replaceAll(root,'<BENCH_ROOT>').replaceAll('<BENCH_ROOT>','<BENCH_ROOT>').replaceAll(repo,'<CEW_SOURCE>')),save=(f,v)=>fs.writeFileSync(p.join(dir,f),JSON.stringify(normalize(v),null,2)+'\n');
save('analysis.json',a);save('posthoc-infinite-stop-probes.json',probe);save('posthoc-infinite-stop-hypothesis.json',h);save('posthoc-infinite-stop-amendment.json',am);const exp=JSON.parse(fs.readFileSync(p.join(dir,'experiment.json')));exp.posthoc_infinite_stop_amendment={...a.posthoc_infinite_stop_amendment,hypothesis_proposed_at:h.proposed_at,actual_probes_started_at:probe.started_at};save('experiment.json',exp);fs.writeFileSync(p.join(dir,'trials.jsonl'),rows.map(r=>JSON.stringify(normalize(r))).join('\n')+'\n');
const csv=fs.readFileSync(p.join(backup,'trials.csv'),'utf8').trimEnd().split('\n').map(s=>s.split(',')),head=csv[0],i=head.indexOf('all_executed_checks_passed');if(i<0||head.includes('posthoc_infinite_stop_passed'))throw Error('Unexpected CSV');head.push('posthoc_infinite_stop_passed');for(const values of csv.slice(1)){const r=rows.find(r=>r.task===values[0]&&r.cell===values[1]&&String(r.run)===values[2]);if(!r)throw Error('CSV identity');values[i]=String(r.all_executed_checks_passed);values.push(r.posthoc_infinite_stop_quality?String(r.posthoc_infinite_stop_quality.cases.every(c=>c.passed)):'');}fs.writeFileSync(p.join(dir,'trials.csv'),csv.map(r=>r.join(',')).join('\n')+'\n');
let text=fs.readFileSync(report,'utf8');if(text.split('INDEPENDENT_REVIEW_PENDING').length!==2)throw Error('Review marker state');const by=Object.fromEntries(a.supplemental_quality_summary.map(r=>[r.cell,r]));
const title='# PR #62 类型交互质量修正与 Fast Path 同批复测';if(!text.startsWith(title))throw Error('Reporttitle');text=text.replace(title,title+'\n\n**最终综合质量：'+by['gpt-fixed'].all_executed_checks_passed+'/14；整批性能FAIL。** 原冻结46项为14/14，但事后8项确认了不同产物中的剩余错误；不能按原46项通过宣称已修复全部质量问题。');
const priorLine=text.split('\n').find(x=>x.startsWith('| 加全部事后6项后的综合检查 |'));if(!priorLine)throw Error('Prior6table row');text=text.replace(priorLine,priorLine+'\n| 加全部事后8项后的综合检查 | '+arms.map(c=>by[c].all_executed_checks_passed+'/14').join(' | ')+' |');
const section=['## 事后发现：无限浮点终点使新搜索无法终止','', '此假设在全部模型结束后提出。先对parent实际执行2次oracle验证，确认构造合法、len快速抛出ValueError；随后对parent、参考和6份原数值产物统一执行相同2项，分别以原版实际异常作预期。起点和步长为整数，终点为正/负无限浮点数。R2的新搜索对始终位于无限终点之前的整数项不断扩展上界，没有终止界限；两项均在2秒被截断。超时记录明确包含ETIMEDOUT和构造成功输出，未把无依据的空退出码当成超时。','',
'| numeric_range版本 | 事后2项无限终点 | 2秒超时数 |','| --- | ---: | ---: | ---: |',...probe.results.map(r=>'| '+r.version+' | '+r.cases.filter(c=>c.passed).length+'/2 | '+r.cases.filter(c=>c.timed_out).length+' |'),'',
'见[原始检查及父版oracle](data/quality-type-interactions-2026-10-19/posthoc-infinite-stop-probes.json)。此组16次统一计分检查，另有2次父版oracle验证，共18次实际进程。原46项、前6项事后检查、所有原产物和token/时间均未改变；54项中只有46项在本轮模型前冻结。',''];
text=text.replace('INDEPENDENT_REVIEW_PENDING',section.join('\n')+'\nINDEPENDENT_REVIEW_PENDING');fs.writeFileSync(report,text);fs.writeFileSync(p.join(root,'posthoc-infinite-stop-amendment.json'),JSON.stringify(am,null,2)+'\n');save('infinite-stop-oracle-validation.json',read('infinite-stop-oracle-validation.json'));console.log(JSON.stringify({status:'ADDED_ACTUAL_POSTHOC_INFINITE_STOP_EVIDENCE',parent:'2/2',all_executed:a.supplemental_quality_summary.map(r=>({cell:r.cell,n:r.all_executed_checks_passed})),version_results:counts,metrics_changed:false}));
